const data = { ...$json.output };

function clean(value) {
  if (value === undefined || value === null) return null;

  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed === '' ? null : trimmed;
  }

  return value;
}

// Limpiar valores
for (const key of [
  'serviceType',
  'vehicleType',
  'brand',
  'model',
  'engine',
  'originalPower',
  'ecuReference',
  'description'
]) {
  data[key] = clean(data[key]);
}

data.year = data.year ?? null;
data.vehicleRunning = data.vehicleRunning ?? null;
data.modifications = data.modifications ?? null;

// Normalizar tipo de vehículo
if (data.vehicleType) {
  const value = data.vehicleType.toLowerCase();

  if (['moto', 'motocicleta', 'motorcycle', 'scooter'].includes(value)) {
    data.vehicleType = 'MOTORCYCLE';
  } else if (['coche', 'car', 'automóvil', 'automovil', 'turismo'].includes(value)) {
    data.vehicleType = 'CAR';
  } else if (['furgoneta', 'van', 'furgón', 'furgon'].includes(value)) {
    data.vehicleType = 'VAN';
  } else if (['camión', 'camion', 'truck'].includes(value)) {
    data.vehicleType = 'TRUCK';
  } else {
    data.vehicleType = 'OTHER';
  }
}

// Campos obligatorios comunes
const required = [
  'brand',
  'model',
  'year'
];

// Campos según el servicio
switch (data.serviceType) {
  case 'REPROGRAMMING':
    required.push(
      'engine',
      'modifications',
      'vehicleRunning'
    );
    break;

  case 'ECU_REPAIR':
    required.push(
      'ecuReference',
      'vehicleRunning'
    );
    break;

  case 'ECU_CLONING':
    required.push(
      'ecuReference'
    );
    break;

  case 'OTHER':
  default:
    break;
}

const missingFields = required.filter((field) => {
  const value = data[field];

  if (value === null || value === undefined || value === '') {
    return true;
  }

  return false;
});

return {
  json: {
    ...data,
    missingFields,
    readyForHandoff: missingFields.length === 0
  }
};

